package li.cil.oc.plusplus;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
import static li.cil.oc.plusplus.BiosCanvasLayout.*;

public class BiosCanvasLayoutTest {
 static final UUID WORLD=UUID.randomUUID(),BINDING=UUID.randomUUID();
 static Axis axis(int x,int y,int z){return new Axis(x,y,z);}
 static Basis north(){return new Basis(axis(0,0,-1),axis(0,1,0));}
 static Cell at(Basis b,int u,int v){return new Cell(WORLD,b.right.x*u+b.up.x*v,b.right.y*u+b.up.y*v,b.right.z*u+b.up.z*v,b,7,0xffffff,UUID.nameUUIDFromBytes((b.normal.x+","+b.normal.y+","+b.normal.z+"/"+b.up.x+","+b.up.y+","+b.up.z+"/"+u+","+v).getBytes(java.nio.charset.StandardCharsets.UTF_8)),BINDING);}
 static List<Cell> grid(Basis b,int w,int h){List<Cell> cells=new ArrayList<>();for(int y=0;y<h;y++)for(int x=0;x<w;x++)cells.add(at(b,x,y));return cells;}
 static double[] hit(Basis b,double u,double v){double[] h={.5,.5,.5};put(h,b.right,u);put(h,b.up,v);put(h,b.normal,1);return h;}
 static void put(double[] h,Axis a,double value){if(a.x!=0)h[0]=a.x>0?value:1-value;else if(a.y!=0)h[1]=a.y>0?value:1-value;else h[2]=a.z>0?value:1-value;}
 static Point map(Group g,Cell c,double u,double v){double[] h=hit(c.basis,u,v);return g.hit(c,c.basis.normal,h[0],h[1],h[2]);}
 @Test public void threeByThreeIsOneCanvasAndOneOrigin(){List<Cell> cells=grid(north(),3,3);List<Group> groups=partition(cells,8,6);assertEquals(1,groups.size());Group g=groups.get(0);assertEquals(3,g.width);assertEquals(3,g.height);assertEquals(9,g.cells.size());int origins=0;for(Cell c:cells)if(g.isOrigin(c))origins++;assertEquals(1,origins);}
 @Test public void allTwentyFourOrientationsShareContinuousInput(){Axis[] axes={axis(1,0,0),axis(-1,0,0),axis(0,1,0),axis(0,-1,0),axis(0,0,1),axis(0,0,-1)};int bases=0;for(Axis n:axes)for(Axis up:axes)if(n.dot(up.x,up.y,up.z)==0){Basis b=new Basis(n,up);List<Cell> cells=grid(b,2,2);Group g=partition(cells,8,6).get(0);assertEquals(4,g.cells.size());Point a=map(g,cells.get(0),1,.5),c=map(g,cells.get(1),0,.5);assertNotNull(a);assertNotNull(c);assertEquals(a.x,c.x,1e-12);assertEquals(a.y,c.y,1e-12);assertEquals(.5,a.x,1e-12);assertTrue(map(g,cells.get(0),.5,.5).y>map(g,cells.get(2),.5,.5).y);bases++;}assertEquals(24,bases);}
 @Test public void joinsAndSplitsHaveNewFingerprintsAndNoHolesOrOverlaps(){List<Cell> cells=grid(north(),3,3);String old=partition(cells,8,6).get(0).fingerprint;cells.remove(4);List<Group> split=partition(cells,8,6);assertTrue(split.size()>1);Set<Cell> seen=new HashSet<>();for(Group g:split){assertEquals(g.width*g.height,g.cells.size());assertNotEquals(old,g.fingerprint);for(Cell c:g.cells)assertTrue(seen.add(c));}assertEquals(8,seen.size());}
 @Test public void configuredEightBySixLimitsAreRetained(){List<Group> normal=partition(grid(north(),8,6),8,6);assertEquals(1,normal.size());List<Group> split=partition(grid(north(),9,7),8,6);int count=0;for(Group g:split){assertTrue(g.width<=8&&g.height<=6);count+=g.cells.size();}assertEquals(63,count);}
 @Test public void differentTierColorBindingPlaneFacingOrWorldDoNotMerge(){Cell a=at(north(),0,0);for(int variant=0;variant<6;variant++){Basis b=variant==4?new Basis(axis(0,0,1),axis(0,1,0)):north();Cell c=new Cell(variant==5?UUID.randomUUID():WORLD,-1,0,variant==3?1:0,b,variant==0?6:7,variant==1?0xabcdef:0xffffff,UUID.randomUUID(),variant==2?UUID.randomUUID():BINDING);assertEquals(2,partition(Arrays.asList(a,c),8,6).size());}}
 @Test public void outerBorderWrongFaceAndMalformedCoordinatesCannotBecomeClicks(){Cell c=at(north(),0,0);Group g=partition(Collections.singleton(c),8,6).get(0);assertNull(map(g,c,0,.5));assertNull(map(g,c,1,.5));assertNull(map(g,c,.5,0));assertNull(map(g,c,.5,1));assertNull(g.hit(c,axis(0,0,1),.5,.5,1));assertNull(g.hit(c,c.basis.normal,Double.NaN,.5,0));assertNull(g.hit(c,c.basis.normal,.5,.5,Double.POSITIVE_INFINITY));assertNull(g.hit(c,c.basis.normal,.5,.5,.5));assertNotNull(map(g,c,.5,.5));}
 @Test public void shuffledInputsAreDeterministicAndReplacementChangesLayout(){List<Cell> cells=grid(north(),3,3);String expected=partition(cells,8,6).get(0).fingerprint;for(int i=0;i<30;i++){Collections.shuffle(cells,new Random(i));assertEquals(expected,partition(cells,8,6).get(0).fingerprint);}Cell old=cells.get(0);Cell replacement=new Cell(old.world,old.x,old.y,old.z,old.basis,old.tier,old.color,UUID.randomUUID(),old.binding);cells.set(0,replacement);assertNotEquals(expected,partition(cells,8,6).get(0).fingerprint);}
 @Test public void extremeWorldCoordinatesUseLongProjection(){Basis b=north();Cell c=new Cell(WORLD,Integer.MIN_VALUE,Integer.MAX_VALUE,Integer.MIN_VALUE,b,7,0xffffff,UUID.randomUUID(),BINDING);assertEquals(2147483648L,c.u);Group g=partition(Collections.singleton(c),8,6).get(0);assertNotNull(map(g,c,.5,.5));}
 @Test public void duplicateIdentitiesPositionsAndOversizedInputAreRejected(){Cell a=at(north(),0,0);for(Collection<Cell> bad:Arrays.asList(Arrays.asList(a,a),grid(north(),257,1),Arrays.asList(a,null))){try{partition(bad,8,6);fail();}catch(IllegalArgumentException expected){}}try{partition(Collections.singleton(a),0,6);fail();}catch(IllegalArgumentException expected){}}
 @Test public void letterboxBarsAreNotInteractiveAndJoinStillUsesSharedCoordinates(){List<Cell> cells=grid(north(),2,1);Group g=partition(cells,8,6).get(0);double[] a=hit(north(),.5,.5);assertNull(g.hit(cells.get(0),north().normal,a[0],a[1],a[2],1));a=hit(north(),1,.5);Point p=g.hit(cells.get(0),north().normal,a[0],a[1],a[2],1);assertNotNull(p);assertEquals(.5,p.x,1e-12);assertEquals(.5,p.y,1e-12);assertNull(g.hit(cells.get(0),north().normal,a[0],a[1],a[2],Double.NaN));}
}
